// Keep customer messages only. Text and photos (prescriptions) are both accepted.
const m = $json.messages?.[0]; if (!m) return [];
return [{ json: { customer_id: m.from, customer_name: $json.contacts?.[0]?.profile?.name || '', wa_phone_id: $json.metadata.phone_number_id,
  type: m.type, text: m.text?.body || m.image?.caption || '', media_id: m.image?.id || '' } }];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { ...$('Normalize Message').first().json, b64: buf.toString('base64'), mime: $input.first().binary.data.mimeType || 'image/jpeg',
  prompt: 'This is a photo of an Egyptian prescription or medicine box. Return JSON only: {"is_prescription": true|false, "readable": true|false, "medicines": [{"name": "", "strength": "", "qty": 1}]}. qty = boxes requested, default 1. Never guess an unreadable name: put it as "?".' } }];

let src; try { src = $('Prepare Prescription Read').first().json; } catch (e) { src = $('Prepare Text Read').first().json; }
let r = $('AI Read Request').first().json; const cat = $('Read Catalog').all().map(i => i.json);
const raw = r?.content?.[0]?.text || r?.choices?.[0]?.message?.content || r?.candidates?.[0]?.content?.parts?.[0]?.text;
if (raw) { try { r = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch (e) { r = { readable: false, medicines: [] }; } }
const norm = s => String(s || '').toLowerCase().replace(/[^a-z0-9\u0600-\u06FF]/g, ''), yes = v => ['yes', 'true', '1'].includes(String(v).trim().toLowerCase());
const lev = (a, b) => { const d = Array.from({ length: a.length + 1 }, (_, i) => Array.from({ length: b.length + 1 }, (_, j) => (i === 0 ? j : j === 0 ? i : 0)));
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)); return d[a.length][b.length]; };
const lines = [], unclear = [];
for (const m of (r.medicines || []).slice(0, 10)) {
  const n = norm(m.name); if (!n || n === '?') { unclear.push(m.name || '?'); continue; }
  const best = cat.map(p => ({ p, d: Math.min(lev(n, norm(p.name)), lev(n, norm(p.active_ingredient))) })).sort((a, b) => a.d - b.d)[0];
  if (!best || best.d > Math.max(2, n.length * 0.3)) { unclear.push(m.name); continue; }
  const p = best.p; const qty = Math.max(1, Math.min(5, Math.round(Number(m.qty) || 1)));
  const alts = cat.filter(x => x.active_ingredient === p.active_ingredient && x.sku !== p.sku && Number(x.stock) > 0);
  lines.push({ sku: p.sku, name: p.name, qty, price_egp: Number(p.price_egp) || 0, in_stock: Number(p.stock) >= qty, controlled: yes(p.controlled), fuzzy: best.d > 0,
    alt: alts[0] ? alts[0].name + ' ' + alts[0].strength + ' (' + alts[0].sku + ', ' + alts[0].price_egp + ' EGP)' : '' });
}
const needsPharmacist = !!r.is_prescription || r.readable === false || unclear.length > 0 || lines.some(l => !l.in_stock || l.controlled || l.fuzzy);
const group = 'R-' + $now.setZone('Africa/Cairo').toFormat('yyMMdd') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
return [{ json: { ...src, b64: undefined, prompt: undefined, group, lines, unclear, readable: r.readable !== false, needsPharmacist, nothing: !lines.length && !unclear.length,
  total: lines.filter(l => l.in_stock).reduce((s, l) => s + l.qty * l.price_egp, 0) } }];

const j = $input.first().json;
const status = j.needsPharmacist ? 'pending_pharmacist' : 'reserved';
const exp = $now.setZone('Africa/Cairo').plus({ hours: 24 })
  .toFormat('yyyy-MM-dd HH:mm');
const base = { customer_id: j.customer_id, wa_phone_id: j.wa_phone_id, customer_name: j.customer_name };
const rows = (j.lines || []).map(l => ({ ...base, sku: l.sku, name: l.name, qty: l.qty, total_egp: l.qty * (l.price || l.price_egp || 0), status, expires_at: status === 'reserved' ? exp : '',
note: [l.controlled ? 'controlled' : '', l.in_stock ? '' : 'out of stock', l.alternative ? 'alt: ' + l.alternative : '', l.fuzzy ? 'fuzzy match' : ''].filter(Boolean).join('; ') }));
for (const u of (j.unclear || [])) rows.push({ ...base, sku: '', name: String(u), qty: 1, total_egp: 0, status: 'pending_pharmacist', expires_at: '', note: 'not in catalog or unreadable' });
return rows.map((r, k) => ({ json: { res_id: j.group + '-' + (k + 1), ...r } }));

// Stock leaves the shelf only when a line is reserved, and never goes below zero.
const cat = Object.fromEntries($('Read Catalog').all().map(i => [i.json.sku, Number(i.json.stock)]));
for (const l of $('Match Catalog').first().json.lines) { cat[l.sku] -= l.qty; if (cat[l.sku] < 0) throw new Error('VALIDATION: stock for ' + l.sku + ' would go negative'); }
return $('Match Catalog').first().json.lines.map(l => ({ json: { sku: l.sku, stock: cat[l.sku] } }));

const q = $json.callback_query;
const [action, group, customer] = String(q.data || '').split('_');

const result = {
  action,
  query_id: q.id,
  chat_id: q.message.chat.id,
  message_id: q.message.message_id,
  original: q.message.text,
  by: q.from.username || q.from.first_name
};

if (group) result.group = group;
if (customer) result.customer = customer;

return [{ json: result }];

const decision = $('Parse Decision').first().json;
const pending = $('Find Pending Lines').all().map(i => i.json);
const catalog = $input.all().map(i => i.json);

// Match by group/res_id if provided, otherwise take all pending_pharmacist lines
const matched = decision.group
  ? pending.filter(r => String(r.res_id || '').includes(decision.group))
  : pending;

if (matched.length === 0) return [];

const isApproved = String(decision.action || '').toLowerCase() === 'approve';
const newStatus = isApproved ? 'reserved' : 'rejected';

// Build reservation updates
const lineUpdates = matched.map(r => ({
  res_id: r.res_id,
  status: newStatus,
  pharmacist: decision.by,
  customer_id: r.customer_id,
  customer_name: r.customer_name,
  sku: r.sku,
  name: r.name,
  qty: Number(r.qty || 1)
}));

// Build catalog stock deductions (only if approved)
const stockUpdates = [];
if (isApproved) {
  const bySku = {};
  for (const r of lineUpdates) {
    bySku[r.sku] = (bySku[r.sku] || 0) + r.qty;
  }
  for (const [sku, deduct] of Object.entries(bySku)) {
    const item = catalog.find(c => c.sku === sku);
    if (item) {
      stockUpdates.push({
        sku,
        new_stock: Math.max(0, Number(item.stock || 0) - deduct)
      });
    }
  }
}

return [{
  json: {
    ...decision,
    is_approved: isApproved,
    new_status: newStatus,
    line_updates: lineUpdates,
    stock_updates: stockUpdates,
    customer_id: lineUpdates[0].customer_id,
    customer_name: lineUpdates[0].customer_name,
    items_summary: lineUpdates.map(l => `${l.qty}x ${l.name}`).join(', ')
  }
}];

const data = $('Apply Decision').first().json;
return data.line_updates.map(line => ({
  json: {
    ...line,
    is_approved: data.is_approved,
    items_summary: data.items_summary
  }
}));

const data = $('Apply Decision').first().json;
return data.stock_updates.map(s => ({
  json: {
    ...s,
    customer_id: data.customer_id,
    customer_name: data.customer_name,
    items_summary: data.items_summary
  }
}));
